def f(x):
    return 1 / x

def approx(a, b, n):
    h = (b - a) / n
    s = 0
    for k in range(n):
        s = s + f(a + k * h + h / 2)
    return h * s

from random import random

def estimation(n):
    compteur = 0
    for k in range(n):
        x = random()
        y = random()
        if x ** 2 + y ** 2 <= 1:
            compteur = compteur + 1
    return compteur / n

def brouncker(n):
    s = 0
    for k in range(1, n + 1):
        s = s + 1 / ((2 * k - 1) * (2 * k))
    return s
